import Foundation
import Testing
import RuneRef
@testable import Rune

@Suite("Backdrop reference parity")
struct BackdropReferenceParityTests {
    @Test func referenceAndGPUAgreeWithRustStartupPainter() throws {
        // Generated by decoding these nine RCB1 records with the Rust startup painter at 842c28c.
        let url = try #require(Bundle.module.url(forResource: "rust-842c28c-backdrop", withExtension: "png", subdirectory: "Fixtures"))
        let oracle = try PortablePNG.decode(Data(contentsOf: url))
        let clip = SIMD4<Float>(0, 0, 96, 64)
        let clear = SIMD4<Float>(0, 0, 0, 1)
        var instances: [RenderInstance] = []
        var primitives: [Primitive] = []
        for x in stride(from: 0, to: 96, by: 16) {
            let rect = SIMD4<Float>(Float(x), 0, 8, 64)
            let white = SIMD4<Float>(repeating: 1)
            instances.append(RenderInstance(rect: rect, fill: white, params: SIMD4(0, KIND_RECT, 0, 1), clip: clip))
            primitives.append(.roundedRect(rect: rect, fill: white, clip: clip))
        }
        let blurs: [(SIMD4<Float>, Float, Float, Float)] = [
            (SIMD4(3, 3, 40, 24), 4, 0.01, 1),
            (SIMD4(49, 5, 42, 40), 6, 9.62, 0.65),
            (SIMD4(8, 36, 43, 23), 5, 28, 1)
        ]
        for (rect, radius, sigma, opacity) in blurs {
            let radii = SIMD4<Float>(repeating: radius)
            let fill = SIMD4<Float>(0, 0, 0, opacity)
            instances.append(RenderInstance(rect: rect, radii: radii, fill: fill, params: SIMD4(sigma, KIND_BACKDROP_BLUR, 0, 1), clip: clip))
            primitives.append(Primitive(rect: rect, radii: radii, fill: fill, params: SIMD4(sigma, Float(PrimitiveKind.backdropBlur.rawValue), 0, 1), clip: clip))
        }
        let frame = RenderFrame(width: 96, height: 64, srgbBlend: true, clearColor: clear, instances: instances)
        let scene = RefScene(width: 96, height: 64, srgbBlend: true, clearColor: clear, primitives: primitives)
        var boot = CpuBootTarget(width: 96, height: 64)
        _ = try CpuBoot.paint(CpuBootScene(frame: frame), into: &boot, threads: 2)
        // The fixture is grayscale, so RGBA and BGRA have identical bytes.
        #expect(boot.pixels == oracle.rgba)
        let expected = Frame(width: 96, height: 64, rgba: oracle.rgba)
        func compare(_ actual: Frame, backend: String) {
            let diff = RuneRef.compare(scene: scene, expected: expected, actual: actual, channelTolerance: 2, maxFailingPixels: 0)
            #expect(diff.passed, "\(backend) against Rust: \(diff)")
        }
        compare(try RuneRef.render(scene), backend: "reference CPU")
        #if canImport(Metal)
        let renderer = try MetalRenderer()
        compare(try renderer.renderOffscreen(frame), backend: "Metal")
        compare(try renderer.renderOffscreen(scene), backend: "reference Metal")
        #endif
        #if canImport(CRuneOffscreenGL)
        let context = try OffscreenGLContext()
        defer { context.close() }
        let gl = try PortableGLRenderer(resolve: OffscreenGLContext.resolve, isGLES: OffscreenGLContext.isGLES)
        defer { gl.close() }
        compare(try context.withFramebuffer(width: 96, height: 64) { try gl.draw(scene) }, backend: "reference GL")
        compare(try context.withFramebuffer(width: 96, height: 64) { try gl.draw(frame) }, backend: "GL")
        #endif
    }
}
